showStatus('\u7B49\u5F85\u624B\u6A5F\u78BA\u8A8D\u2026\uFF08\u4E8C\u7DAD\u78BC\u6709\u6548\u671F ' + Math.floor((Number(d.expires_in) || 600) / 60) + ' \u5206\u9418\uFF09');
